//! SAME fallible output String kernel for native producer and returned report.
//! No source/model/diagnostic authority; caller retains actual output credit.
use crate::{SettingAdmission,SettingRootLease};
use std::io;
fn poll(a:&SettingAdmission<'_>)->io::Result<()>{let result=a.checkpoint();if let Some(actual)=a.take_operational_error(){return Err(actual)}result}
struct MessageWriter<'a,'b,'c>{text:String,a:&'a SettingAdmission<'b>,credit:&'c mut SettingRootLease,error:Option<io::Error>}
impl std::fmt::Write for MessageWriter<'_,'_,'_>{fn write_str(&mut self,text:&str)->std::fmt::Result{if self.error.is_some(){return Err(std::fmt::Error)}let result=(||{poll(self.a)?;let needed=self.text.len().checked_add(text.len()).ok_or(io::ErrorKind::OutOfMemory)?;if needed>self.text.capacity(){let old=self.text.capacity();let target=needed.max(old.checked_mul(2).ok_or(io::ErrorKind::OutOfMemory)?);let peak=target.checked_mul(4).ok_or(io::ErrorKind::OutOfMemory)?;self.a.grow(self.credit,peak).map_err(|e|self.a.take_operational_error().unwrap_or(e))?;self.text.try_reserve_exact(target-self.text.len()).map_err(|error|io::Error::new(io::ErrorKind::OutOfMemory,error))?;if self.text.capacity()>peak{return Err(io::ErrorKind::OutOfMemory.into())}let free=old.checked_add(peak).and_then(|n|n.checked_sub(self.text.capacity())).ok_or(io::ErrorKind::InvalidData)?;self.a.shrink(self.credit,free).map_err(|e|self.a.take_operational_error().unwrap_or(e))?;}self.text.push_str(text);Ok(())})();if let Err(error)=result{self.error=Some(error);return Err(std::fmt::Error)}Ok(())}}
pub fn message_using(a:&SettingAdmission<'_>,credit:&mut SettingRootLease,render:impl FnOnce(&mut dyn std::fmt::Write)->std::fmt::Result)->io::Result<String>{let mut writer=MessageWriter{text:String::new(),a,credit,error:None};let result=render(&mut writer);if let Some(error)=writer.error{return Err(error)}if result.is_err(){return Err(io::Error::new(io::ErrorKind::InvalidData,"actual formal diagnostic writer failed without an operational cause"))}Ok(writer.text)}

#[cfg(test)]mod tests{use super::*;use std::sync::{atomic::{Ordering}};
 #[test]fn actual_common_admitted_writer_retains_string_capacity_under_callers_same_credit(){let used=crate::SettingChargeCounter::try_new(crate::SettingChargeCounter::root_allocation_bytes()).unwrap();let a=SettingAdmission::new(&used,1<<20,&||Ok(()));let mut credit=a.reserve(0).unwrap();let text=message_using(&a,&mut credit,|out|out.write_str("actual output")).unwrap();assert_eq!(text,"actual output");assert!(credit.bytes()>=text.capacity());drop(text);drop(credit);assert_eq!(used.load(Ordering::Acquire),crate::SettingChargeCounter::root_allocation_bytes());}
 #[test]fn actual_common_writer_preserves_typed_first_io_and_refuses_quota_before_growth(){let used=crate::SettingChargeCounter::try_new(crate::SettingChargeCounter::root_allocation_bytes()).unwrap();let tiny=SettingAdmission::new(&used,crate::SettingChargeCounter::root_allocation_bytes() + (1),&||Ok(()));let mut credit=tiny.reserve(0).unwrap();assert_eq!(message_using(&tiny,&mut credit,|out|out.write_str("too much")).unwrap_err().kind(),io::ErrorKind::OutOfMemory);drop(credit);let fail=||Err(io::Error::from_raw_os_error(1450));let a=SettingAdmission::new(&used,1<<20,&fail);let mut credit=SettingRootLease::reserve(&used,1<<20,0).unwrap();assert_eq!(message_using(&a,&mut credit,|out|out.write_str("not allocated")).unwrap_err().raw_os_error(),Some(1450));drop(credit);assert_eq!(used.load(Ordering::Acquire),crate::SettingChargeCounter::root_allocation_bytes());}
}
